package ru.neverland.minttrade;
import java.nio.file.*;import java.util.*;import java.util.concurrent.*;
import ru.neverland.core.*;import ru.neverland.minttrade.contract.*;import ru.neverland.minttrade.integration.TreasuryFunding;
import static ru.neverland.minttrade.contract.SupplyContract.*;
public final class SupplyJournalSmoke{
 static int checks;static void check(boolean b,String why){if(!b)throw new AssertionError(why);checks++;}static <T>T await(CompletionStage<T> stage)throws Exception{return stage.toCompletableFuture().get(5,TimeUnit.SECONDS);}interface Work{void run()throws Exception;}static void rejects(Work work,String why)throws Exception{try{work.run();}catch(Exception expected){checks++;return;}throw new AssertionError(why);}
 static SupplyContract contract(UUID seller,UUID buyer){return SupplyContract.proposal(new Terms(UUID.randomUUID(),seller,buyer,"encoded-example","Камень",64,15000,1,1000,100000)).accept(buyer,2000);}
 public static void main(String[] args)throws Exception{
  Path folder=Files.createTempDirectory("supply-async-journal"),file=folder.resolve("contracts-data.yml");UUID seller=UUID.randomUUID(),buyer=UUID.randomUUID(),actor=UUID.randomUUID();var legacy=contract(seller,buyer);legacy=legacy.attempt(new Attempt(UUID.randomUUID(),Phase.DEBIT_PENDING,3000),3000,"Unknown old debit");var old=new SupplyRepository(file);old.load();old.put(legacy);byte[] prior=Files.readAllBytes(file);var repo=new SupplyJournal(file);repo.load();check(repo.image().contracts().get(legacy.terms().id()).equals(legacy)&&repo.image().payments().isEmpty(),"schema1 unknown old debit is imported without invented Treasury authorization");check(Arrays.equals(prior,Files.readAllBytes(file)),"loading additive journal never rewrites old data");
  var base=contract(seller,buyer);await(repo.put(base,actor,null,false,List.of(),null));var attempted=base.attempt(new Attempt(UUID.randomUUID(),Phase.DEBIT_READY,4000),4000,"Prepared budget intent");var terms=new TreasuryFunding.Terms(SupplyJournal.debit(attempted.attempt().id()),buyer,new UUID(0,0),15000,"infrastructure","trade","Exact supply "+attempted.attempt().id());var payment=new SupplyJournal.Payment(attempted.attempt().id(),"TREASURY",terms);var before=repo.image();var lock=CaravanEffectsSmoke.lock(file);lock.lock();CompletionStage<SupplyContract> commit;try{commit=repo.put(attempted,null,payment,false,List.of(),null);check(!commit.toCompletableFuture().isDone()&&repo.image()==before&&repo.busy(),"funding marker and debit-ready phase are unpublished before physical ACK");long deadline=System.nanoTime()+TimeUnit.SECONDS.toNanos(2);while(!lock.hasQueuedThreads()&&System.nanoTime()<deadline)Thread.sleep(1);check(lock.hasQueuedThreads()&&SuiteState.tryRun("supply writer contention",()->{}),"held supply writer leaves suite state available");rejects(()->await(repo.put(base,null,null,false,List.of(),null)),"overlapping snapshots cannot bypass the ACK gate");}finally{lock.unlock();}await(commit);check(repo.image().payments().get(base.terms().id()).terms().equals(terms),"exact attempt UUID actor budget and cents publish together after ACK");rejects(()->await(repo.put(attempted,UUID.randomUUID(),null,false,List.of(),null)),"historical agreement actor cannot be changed by a later attempt");
  var debt=attempted.attempt(attempted.attempt().phase(Phase.DEBIT_PENDING),5000,"Awaiting Treasury");await(repo.put(debt,null,null,false,List.of(),null));var restartActor=repo.image().actors().get(base.terms().id());await(repo.close());var restart=new SupplyJournal(file);restart.load();check(restart.image().payments().get(base.terms().id()).equals(payment)&&restart.image().actors().get(base.terms().id()).equals(restartActor),"restart retains complete budget protocol without replaying a synchronous debit");check(restart.image().contracts().get(legacy.terms().id()).attempt().phase()==Phase.DEBIT_PENDING&&!restart.image().payments().containsKey(legacy.terms().id()),"new protocol never reclassifies historical ambiguous pending debit");
  var record=new AuditRecord(AuditRecord.id("NeverLandTownyTrade",debt.attempt().id().toString(),"PAID"),6000,"NeverLandTownyTrade","SUPPLY_DEAL","PAID",debt.attempt().id().toString(),AuditRecord.Party.system(),new AuditRecord.Party("TOWN",seller.toString(),"Seller",seller.toString()),new AuditRecord.Party("TOWN",buyer.toString(),"Buyer",buyer.toString()),"STONE",64,"150.00","Frozen supply snapshot");var outcome=ReputationOutcome.town("supply-complete:"+debt.attempt().id(),seller,"SUPPLY_COMPLETED",6000,"Completed test supply");await(restart.put(debt,null,null,false,List.of(outcome),record));await(restart.close());var third=new SupplyJournal(file);third.load();check(third.image().audit().equals(List.of(record))&&third.image().reputation().get(outcome.id()).equals(outcome),"audit and reputation obligations survive restart in the same financial snapshot");await(third.auditAck(record.id()));await(third.reputationAck(outcome.id()));check(third.image().audit().isEmpty()&&third.image().reputation().isEmpty(),"only individually acknowledged obligations are removed");await(third.close());
  Path broken=folder.resolve("broken.yml");Files.writeString(broken,"schema: 2\ncontracts: {}\nreputation-outbox: broken\n");var invalid=new SupplyJournal(broken);rejects(invalid::load,"malformed outbox is not silently replaced by an empty list");await(invalid.close());check(Files.readString(broken).contains("reputation-outbox: broken"),"shutdown preserves unread obligations");
  var missing=new HashMap<>(Map.of(attempted.terms().id(),attempted));rejects(()->new SupplyJournal.Image(missing,Map.of(),Map.of(),Map.of(),List.of()),"debit-ready row requires its matching durable protocol marker");
  var pending=new Attempt(UUID.randomUUID(),Phase.CREDIT_PENDING,1000,10,System.currentTimeMillis()+60000);var retry=pending.phase(Phase.DELIVERED).phase(Phase.CREDIT_PENDING);
  check(!retry.auditStep().equals(pending.auditStep())&&retry.revision()==12,"manual unpaid retry has a new persisted audit identity for the same credit");
  check(retry.transitionedAt()>pending.transitionedAt()&&retry.started()==pending.started(),"audit chronology remains strict if clock moves backwards");
  check(retry.phase(Phase.CREDIT_PENDING).equals(retry),"observing same phase does not invent another transition");
  check(retry.auditOutcome().equals("REVIEW_CREDIT")&&retry.phase(Phase.COMPLETE).auditOutcome().equals("COMPLETED"),"admin signals understand waiting and completed supply phases");
  var yaml=new org.bukkit.configuration.file.YamlConfiguration();var retryContract=base.attempt(retry,6000,"Verified retry");SupplyRepository.write(yaml,retryContract);check(SupplyRepository.read(base.terms().id(),yaml).equals(retryContract),"audit sequence and transition time survive legacy repository codec round trip");
  rejects(()->new Attempt(UUID.randomUUID(),Phase.PAID,1000,-1,1000),"invalid persisted audit revision is rejected");
  System.out.println("SupplyJournalSmoke PASS "+checks+" checks");
 }
}
